mapper.select:
SELECT t.keeper_id, t.keeper_name, COUNT(CASE WHEN FALSE = ISNULL( t.sign_in_status ) AND t.sign_in_status <> '1' THEN 1 END) + COUNT(CASE WHEN FALSE = ISNULL( t.sign_out_status ) AND t.sign_out_status <> '4' THEN 1 END) + COUNT(CASE WHEN TRUE = ISNULL( t.sign_in_status ) AND NOW() > CONCAT( t.attendance_date, ' ', t.sign_in_time ) THEN 1 END) + COUNT(CASE WHEN TRUE = ISNULL( t.sign_out_status ) AND NOW() > CONCAT( t.attendance_date, ' ', t.sign_out_time ) THEN 1 END) AS dbnormal_count, COUNT( CASE WHEN t.sign_in_status = '1' THEN 1 END ) + COUNT( CASE WHEN t.sign_out_status = '4' THEN 1 END ) AS normal_count, t.industry_code, t.app_ver_code, t.tenant_id, MAX( t.sign_in_add_time ) create_time, t.grid_id FROM bm_attendance_line t WHERE t.tenant_id = #{tenantId} AND t.industry_code = #{industryCode} AND t.delete_flag = '0'
AND t.attendance_date >= #{startDate}
AND t.attendance_date <= #{endDate}
AND t.grid_id = #{gridId}
AND (t.keeper_id like concat('%',#{keeperName},'%') OR t.keeper_name like concat('%',#{keeperName},'%'))
GROUP BY t.keeper_id, t.grid_id ORDER BY create_time DESC

SELECT t.keeper_id,t.keeper_name,t.`date`,t.`time`,t.`status`,t.keeperId,t.industryCode,t.tenantId,t.sign_in_time,t.sign_out_time,t.type,t.grid_id FROM (
SELECT a.keeper_id,a.keeper_name,a.attendance_date AS `date`,
       a.sign_in_time,a.sign_out_time,'1' as type,
IFNULL(DATE_FORMAT(a.sign_in_add_time, '%H:%i:%s'),'-') AS `time`,a.sign_in_status AS `status`,
       a.keeper_id keeperId,
       a.industry_code industryCode,
       a.tenant_id tenantId,
       a.grid_id
FROM bm_attendance_line a
WHERE a.keeper_id = #{keeperId} AND a.grid_id = #{gridId}

    ${dataScope}


    AND a.attendance_date >= #{startDate}


    AND a.attendance_date <= #{endDate}


    AND a.sign_in_status = #{status}


    AND a.sign_in_status = '3' AND a.sign_out_status = '6'

UNION ALL
SELECT a.keeper_id,a.keeper_name,a.attendance_date AS `date`,
a.sign_in_time,a.sign_out_time,'2' as type,
IFNULL(DATE_FORMAT(a.sign_out_add_time, '%H:%i:%s'),'-') AS `time`,a.sign_out_status AS `status`,
       a.keeper_id keeperId,
       a.industry_code industryCode,
       a.tenant_id tenantId,
       a.grid_id
FROM bm_attendance_line a
WHERE a.keeper_id = #{keeperId} AND a.grid_id = #{gridId}

    ${dataScope}


    AND a.attendance_date >= #{startDate}


    AND a.attendance_date <= #{endDate}


    AND a.sign_out_status = #{status}


    AND a.sign_in_status = '3' AND a.sign_out_status = '6'

) t ORDER BY t.`date` DESC, t.type DESC

select

from bm_attendance_set
where tenant_id = #{tenantId}

    AND industry_code = #{industryCode}

        SELECT attendance_id,tenant_id, keeper_id, keeper_name, IFNULL(sign_in_status,'3') AS sign_in_status, sign_in_add_time,
        IFNULL(sign_out_status,'6') AS sign_out_status, sign_out_add_time, attendance_date, create_time, sign_in_time, sign_out_time,
        sign_begin,sign_end,bus_in_time,bus_out_time,tenant_id,industry_code,app_ver_code,sign_in_address
	    FROM bm_attendance_line


                AND keeper_id = #{keeperId}


                AND attendance_date = #{attendanceDate}


                AND tenant_id = #{tenantId}


                AND industry_code = #{industryCode}


                AND grid_id = #{gridId}

SELECT
a.attendance_date AS `date`,
(CASE WHEN a.sign_in_status = '1' AND a.sign_out_status = '4' THEN '正常' ELSE '异常' END) AS `status`
FROM
bm_attendance_line a
WHERE a.attendance_date != DATE_FORMAT(NOW(), '%Y-%m-%d')
    AND DATE_FORMAT(a.attendance_date, '%Y-%m') = #{month}
    AND a.keeper_id = #{keeperId}
    AND a.grid_id = #{gridId}

    AND a.tenant_id = #{tenantId}


    AND a.industry_code = #{industryCode}

SELECT t.normal_count,( t.all_count - t.normal_count ) AS dbnormal_count, #{month} AS MONTH, t.keeper_id, t.grid_id, t.tenant_id, t.industry_code FROM ( SELECT COUNT( CASE WHEN a.sign_in_status = '1' AND a.sign_out_status = '4' THEN 1 END ) AS normal_count, COUNT( 1 ) AS all_count, a.attendance_date, a.keeper_id, a.grid_id, a.tenant_id, a.industry_code FROM bm_attendance_line a WHERE date_format(a.attendance_date, '%Y-%m') = #{month} AND date_format(now(), '%Y-%m-%d') > a.attendance_date AND a.keeper_id = #{keeperId}
AND a.tenant_id = #{tenantId}
AND a.industry_code = #{industryCode}
AND a.grid_id = #{gridId}
) t

SELECT
    COUNT( CASE WHEN a.sign_in_status = '1' AND a.sign_out_status = '4' THEN 1 END ) AS normal_count,
    COUNT( CASE WHEN a.sign_in_status = '2' THEN 1 END ) + COUNT( CASE WHEN a.sign_out_status = '5' THEN 1 END ) AS abnormal_count,
    COUNT( CASE WHEN a.sign_in_status = '3' THEN 1 END ) + COUNT( CASE WHEN a.sign_out_status = '6' THEN 1 END ) AS lack_count
FROM bm_attendance_line a
WHERE DATE_FORMAT( a.attendance_date, '%Y-%m' ) = DATE_FORMAT( now(), '%Y-%m' )
AND a.keeper_id = #{keeperId} AND a.grid_id = #{gridId}

    AND a.tenant_id = #{tenantId}


    AND a.industry_code = #{industryCode}

SELECT sign_in_status, sign_out_status, sign_in_time, sign_out_time
FROM bm_attendance_line


        AND keeper_id = #{keeperId}


        AND attendance_date = #{attendanceDate}


        AND tenant_id = #{tenantId}


        AND industry_code = #{industryCode}


        AND grid_id = #{gridId}

SELECT b.NICK_NAME, b.AVATAR, a.keeper_id FROM bm_gridkeeper a LEFT JOIN sys_user b ON a.staff_id = b.USER_ID WHERE a.delete_flag = 0 AND a.status = '0' and b.DEL_FLAG = '0' and b.STATUS = '0'
AND a.login_name = #{userName}
AND a.tenant_id = #{tenantId}
AND a.industry_code = #{industryCode}

SELECT a.keeper_id, a.keeper_name, b.grid_id, c.grid_name FROM bm_gridkeeper a LEFT JOIN bm_grid_keeper_ref b ON a.keeper_id = b.keeper_id LEFT JOIN bm_grid c ON b.grid_id = c.grid_id WHERE a.delete_flag = 0 AND b.delete_flag = 0 and c.delete_flag = 0
AND a.keeper_id = #{keeperId}
order by c.grid_level,CASE WHEN SUBSTRING( grid_name, 1, 1 ) REGEXP '[一-龥]' THEN firstPinyin ( grid_name ) ELSE SUBSTRING( grid_name, 1, 1 ) END

select dict_value
from sys_dict_data
where status = '0' and dict_type = #{dictType} and dict_label = #{week}

SELECT distinct grid_id
FROM bm_attendance_line
WHERE  keeper_id = #{keeperId}
  AND attendance_date = #{attendanceDate}
